begin
for x in select value from jsonb_array_elements('[{"identity":"repo:https://github.com/black-forest-labs/flux","slug":"flux-495a3c30","name":"FLUX","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một họ model cho tạo hình, sửa ảnh và điều khiển bố cục — không cùng một giấy phép.","description":"Repo FLUX của Black Forest Labs cung cấp mã suy luận tối thiểu cho các model open-weight. Bảng chính chủ phân biệt tạo ảnh, sửa vùng, điều kiện cạnh/độ sâu, biến thể và Kontext. Người làm nội dung cần chọn đúng model theo việc cần làm, thay vì coi FLUX là một nút chung.","long_description":"ĐIỂM NỔI BẬT\n• Schnell/dev cho text-to-image; Fill cho in/out-painting.\n• Canny/Depth cho điều kiện cấu trúc, Redux cho biến thể.\n• Kontext cho sửa ảnh; có hướng dẫn model local và dịch vụ API riêng.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử bố cục ảnh quảng bá rồi dùng model chỉnh sửa phù hợp để thay chi tiết mà không xây lại toàn bộ cảnh.\n\nBẮT ĐẦU\nĐọc bảng model và giấy phép trước, sau đó chọn workflow/môi trường tương ứng.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nSchnell Apache-2.0 nhưng nhiều trọng số dev mang giấy phép phi thương mại riêng; quyền model/API/đầu ra không được gộp chung. Pro không phải trọng số mở trong repo này.","canonical_url":"https://github.com/black-forest-labs/flux","repository_url":"https://github.com/black-forest-labs/flux","documentation_url":"https://raw.githubusercontent.com/black-forest-labs/flux/main/README.md","owner_name":"black-forest-labs","license":"Theo model: Schnell Apache-2.0; nhiều bản dev dùng FLUX.1-dev Non-Commercial License.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":61,"categories":["image","design"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Một họ model cho tạo hình, sửa ảnh và điều khiển bố cục — không cùng một giấy phép. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một họ model cho tạo hình, sửa ảnh và điều khiển bố cục — không cùng một giấy phép.","highlights":["Schnell/dev cho text-to-image; Fill cho in/out-painting.","Canny/Depth cho điều kiện cấu trúc, Redux cho biến thể.","Kontext cho sửa ảnh; có hướng dẫn model local và dịch vụ API riêng."],"example":"Thử bố cục ảnh quảng bá rồi dùng model chỉnh sửa phù hợp để thay chi tiết mà không xây lại toàn bộ cảnh.","setup":"Đọc bảng model và giấy phép trước, sau đó chọn workflow/môi trường tương ứng.","limitations":"Schnell Apache-2.0 nhưng nhiều trọng số dev mang giấy phép phi thương mại riêng; quyền model/API/đầu ra không được gộp chung. Pro không phải trọng số mở trong repo này.","github":{"stars":25938,"forks":1913,"observedAt":"2026-09-03T16:08:54.574Z","url":"https://github.com/black-forest-labs/flux","pushedAt":"2025-07-31T13:58:55Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/black-forest-labs/flux/main/README.md","observedAt":"2026-09-03T16:10:30.775Z","sha256":"d87b208a6a7b4669f08fa1882025c6fe825ee29605b0250d0b9f56b36ce27078"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"black-forest-labs/flux:metadata","source_url":"https://github.com/black-forest-labs/flux","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AAcly%2Fkrita-ai-diffusion%20repo%3ASanster%2FIOPaint%20repo%3Aupscayl%2Fupscayl%20repo%3Axinntao%2FReal-ESRGAN%20repo%3AQwenLM%2FQwen-Image%20repo%3Ablack-forest-labs%2Fflux%20repo%3ATencent-Hunyuan%2FHunyuan3D-2%20repo%3Amicrosoft%2FTRELLIS&per_page=100","stars":25938,"forks":1913,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:08:54.574Z"},{"source_type":"github","source_identifier":"black-forest-labs/flux:readme:d87b208a6a7b4669f08fa1882025c6fe825ee29605b0250d0b9f56b36ce27078","source_url":"https://raw.githubusercontent.com/black-forest-labs/flux/main/README.md","raw_metadata":{"sha256":"d87b208a6a7b4669f08fa1882025c6fe825ee29605b0250d0b9f56b36ce27078","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:30.775Z"}],"expected":null},{"identity":"repo:https://github.com/tencent-hunyuan/hunyuan3d-2","slug":"hunyuan3d-2-3bae0769","name":"Hunyuan3D 2","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Từ ảnh tham chiếu tới vật thể 3D để thử góc quay và visual sản phẩm.","description":"Hunyuan3D 2 tách tạo hình khối và tạo texture thành hai giai đoạn. Creator có thể dùng đầu ra làm tư liệu cho cảnh 3D hoặc thử ý tưởng, nhưng vẫn cần kiểm tra hình học, bề mặt và quyền đối với vật thể tham chiếu.","long_description":"ĐIỂM NỔI BẬT\n• Tạo mesh theo ảnh rồi sinh texture cho mesh.\n• Có model nhỏ/turbo và hướng đa góc nhìn.\n• README dẫn Blender addon cùng các tích hợp cộng đồng.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nTạo bản nháp vật thể hư cấu từ concept của bạn rồi thử góc máy trong phần mềm 3D.\n\nBẮT ĐẦU\nChọn model đúng phiên bản; README nêu khoảng 6GB VRAM cho shape và 16GB cho cả shape/texture ở cấu hình được mô tả.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông bảo đảm topology dùng được ngay cho animation hoặc sản xuất. Repo cũng dẫn 2.1/2.5 ở nơi khác; không trộn tính năng hay giấy phép giữa các bản.","canonical_url":"https://github.com/Tencent-Hunyuan/Hunyuan3D-2","repository_url":"https://github.com/Tencent-Hunyuan/Hunyuan3D-2","documentation_url":"https://raw.githubusercontent.com/Tencent-Hunyuan/Hunyuan3D-2/main/README.md","owner_name":"Tencent-Hunyuan","license":"Giấy phép Tencent Hunyuan theo model; cần đọc điều kiện thay vì suy diễn từ mã công khai.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":62,"categories":["image","design","video"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Từ ảnh tham chiếu tới vật thể 3D để thử góc quay và visual sản phẩm. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Từ ảnh tham chiếu tới vật thể 3D để thử góc quay và visual sản phẩm.","highlights":["Tạo mesh theo ảnh rồi sinh texture cho mesh.","Có model nhỏ/turbo và hướng đa góc nhìn.","README dẫn Blender addon cùng các tích hợp cộng đồng."],"example":"Tạo bản nháp vật thể hư cấu từ concept của bạn rồi thử góc máy trong phần mềm 3D.","setup":"Chọn model đúng phiên bản; README nêu khoảng 6GB VRAM cho shape và 16GB cho cả shape/texture ở cấu hình được mô tả.","limitations":"Không bảo đảm topology dùng được ngay cho animation hoặc sản xuất. Repo cũng dẫn 2.1/2.5 ở nơi khác; không trộn tính năng hay giấy phép giữa các bản.","github":{"stars":14729,"forks":1527,"observedAt":"2026-09-03T16:08:54.574Z","url":"https://github.com/Tencent-Hunyuan/Hunyuan3D-2","pushedAt":"2025-10-28T09:58:12Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/Tencent-Hunyuan/Hunyuan3D-2/main/README.md","observedAt":"2026-09-03T16:10:32.423Z","sha256":"edc4d006b977c8e28a0d3135ffc22b0dcad8e8dcb31fc9152c906eb21e29a886"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"Tencent-Hunyuan/Hunyuan3D-2:metadata","source_url":"https://github.com/Tencent-Hunyuan/Hunyuan3D-2","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AAcly%2Fkrita-ai-diffusion%20repo%3ASanster%2FIOPaint%20repo%3Aupscayl%2Fupscayl%20repo%3Axinntao%2FReal-ESRGAN%20repo%3AQwenLM%2FQwen-Image%20repo%3Ablack-forest-labs%2Fflux%20repo%3ATencent-Hunyuan%2FHunyuan3D-2%20repo%3Amicrosoft%2FTRELLIS&per_page=100","stars":14729,"forks":1527,"license":"NOASSERTION"},"fetched_at":"2026-09-03T16:08:54.574Z"},{"source_type":"github","source_identifier":"Tencent-Hunyuan/Hunyuan3D-2:readme:edc4d006b977c8e28a0d3135ffc22b0dcad8e8dcb31fc9152c906eb21e29a886","source_url":"https://raw.githubusercontent.com/Tencent-Hunyuan/Hunyuan3D-2/main/README.md","raw_metadata":{"sha256":"edc4d006b977c8e28a0d3135ffc22b0dcad8e8dcb31fc9152c906eb21e29a886","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:32.423Z"}],"expected":null},{"identity":"repo:https://github.com/microsoft/trellis","slug":"trellis-841492f6","name":"TRELLIS","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Một ý tưởng hình ảnh có thể trở thành tài nguyên 3D ở nhiều định dạng.","description":"TRELLIS của Microsoft tạo tài nguyên 3D từ ảnh hoặc chữ, với đầu ra như mesh, Gaussian và radiance field. Dự án phù hợp thử concept/vật thể cho video, có biến thể và chỉnh cục bộ. Chính chủ khuyên tạo ảnh tốt trước rồi dùng nhánh image-to-3D để có chi tiết hơn nhánh text trực tiếp.","long_description":"ĐIỂM NỔI BẬT\n• Có nhiều định dạng đầu ra 3D theo pipeline.\n• Tạo biến thể và chỉnh một phần tài nguyên.\n• Có ví dụ, demo Gradio và model text/image riêng.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nChọn một ảnh concept rõ ràng của vật thể gốc, tạo mesh thử rồi kiểm tra từ nhiều góc.\n\nBẮT ĐẦU\nCấu hình được kiểm thử là Linux, NVIDIA ít nhất 16GB VRAM; cần môi trường và phụ thuộc biên dịch.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nKhông phải tool nhẹ cho laptop phổ thông. Đa ảnh là phương pháp có giới hạn; phần lớn code/model MIT nhưng một số submodule mang giấy phép khác.","canonical_url":"https://github.com/microsoft/TRELLIS","repository_url":"https://github.com/microsoft/TRELLIS","documentation_url":"https://raw.githubusercontent.com/microsoft/TRELLIS/main/README.md","owner_name":"microsoft","license":"Model và phần lớn code MIT; diffoctreerast, Modified Flexicubes có giấy phép riêng.","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":63,"categories":["image","design","video"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Một ý tưởng hình ảnh có thể trở thành tài nguyên 3D ở nhiều định dạng. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Một ý tưởng hình ảnh có thể trở thành tài nguyên 3D ở nhiều định dạng.","highlights":["Có nhiều định dạng đầu ra 3D theo pipeline.","Tạo biến thể và chỉnh một phần tài nguyên.","Có ví dụ, demo Gradio và model text/image riêng."],"example":"Chọn một ảnh concept rõ ràng của vật thể gốc, tạo mesh thử rồi kiểm tra từ nhiều góc.","setup":"Cấu hình được kiểm thử là Linux, NVIDIA ít nhất 16GB VRAM; cần môi trường và phụ thuộc biên dịch.","limitations":"Không phải tool nhẹ cho laptop phổ thông. Đa ảnh là phương pháp có giới hạn; phần lớn code/model MIT nhưng một số submodule mang giấy phép khác.","github":{"stars":13569,"forks":1331,"observedAt":"2026-09-03T16:08:54.574Z","url":"https://github.com/microsoft/TRELLIS","pushedAt":"2026-06-26T07:27:56Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/microsoft/TRELLIS/main/README.md","observedAt":"2026-09-03T16:10:32.980Z","sha256":"675a1bab7837d22972a776dec8e2a2eb01f9211bd40b4c57112a8335ccb9ec3e"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"microsoft/TRELLIS:metadata","source_url":"https://github.com/microsoft/TRELLIS","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AAcly%2Fkrita-ai-diffusion%20repo%3ASanster%2FIOPaint%20repo%3Aupscayl%2Fupscayl%20repo%3Axinntao%2FReal-ESRGAN%20repo%3AQwenLM%2FQwen-Image%20repo%3Ablack-forest-labs%2Fflux%20repo%3ATencent-Hunyuan%2FHunyuan3D-2%20repo%3Amicrosoft%2FTRELLIS&per_page=100","stars":13569,"forks":1331,"license":"MIT"},"fetched_at":"2026-09-03T16:08:54.574Z"},{"source_type":"github","source_identifier":"microsoft/TRELLIS:readme:675a1bab7837d22972a776dec8e2a2eb01f9211bd40b4c57112a8335ccb9ec3e","source_url":"https://raw.githubusercontent.com/microsoft/TRELLIS/main/README.md","raw_metadata":{"sha256":"675a1bab7837d22972a776dec8e2a2eb01f9211bd40b4c57112a8335ccb9ec3e","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:32.980Z"}],"expected":null},{"identity":"repo:https://github.com/lllyasviel/stable-diffusion-webui-forge","slug":"stable-diffusion-webui-forge-2f15b1e6","name":"Stable Diffusion WebUI Forge","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Giữ cách dùng WebUI quen thuộc, có thêm lựa chọn quản lý bộ nhớ và model.","description":"Forge xây trên Stable Diffusion WebUI để tối ưu quản lý tài nguyên và thử các tính năng mới. Nó có tài liệu riêng về FLUX, GGUF/NF4, LoRA và offload. Đây là nhánh phục vụ creator dùng model local, không phải lời hứa nhanh hơn trong mọi cấu hình.","long_description":"ĐIỂM NỔI BẬT\n• Điều chỉnh GPU weight, offload và swap theo model.\n• Hỗ trợ các định dạng model lượng tử hóa được README liệt kê.\n• Có danh sách extension tương thích và gói cài kèm môi trường.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử cùng một workflow hình trên cấu hình vừa bộ nhớ, ghi lại thời gian và chất lượng trước khi xử lý theo lô.\n\nBẮT ĐẦU\nChọn gói/môi trường chính chủ, đọc hướng dẫn đúng model và kiểm tra extension từng cái.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nMột số bảng kiểm thử trong README có ngày cũ, không phải chứng nhận tương thích hiện tại. Không đặt GPU weight quá cao; quyền model không thay đổi chỉ vì chạy bằng Forge.","canonical_url":"https://github.com/lllyasviel/stable-diffusion-webui-forge","repository_url":"https://github.com/lllyasviel/stable-diffusion-webui-forge","documentation_url":"https://raw.githubusercontent.com/lllyasviel/stable-diffusion-webui-forge/main/README.md","owner_name":"lllyasviel","license":"AGPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":64,"categories":["image","design"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Giữ cách dùng WebUI quen thuộc, có thêm lựa chọn quản lý bộ nhớ và model. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Giữ cách dùng WebUI quen thuộc, có thêm lựa chọn quản lý bộ nhớ và model.","highlights":["Điều chỉnh GPU weight, offload và swap theo model.","Hỗ trợ các định dạng model lượng tử hóa được README liệt kê.","Có danh sách extension tương thích và gói cài kèm môi trường."],"example":"Thử cùng một workflow hình trên cấu hình vừa bộ nhớ, ghi lại thời gian và chất lượng trước khi xử lý theo lô.","setup":"Chọn gói/môi trường chính chủ, đọc hướng dẫn đúng model và kiểm tra extension từng cái.","limitations":"Một số bảng kiểm thử trong README có ngày cũ, không phải chứng nhận tương thích hiện tại. Không đặt GPU weight quá cao; quyền model không thay đổi chỉ vì chạy bằng Forge.","github":{"stars":12986,"forks":1714,"observedAt":"2026-09-03T16:09:01.022Z","url":"https://github.com/lllyasviel/stable-diffusion-webui-forge","pushedAt":"2025-07-31T01:33:17Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/lllyasviel/stable-diffusion-webui-forge/main/README.md","observedAt":"2026-09-03T16:10:39.617Z","sha256":"e99a0cdc5711816a3da4edb1d70f41dcf3396a6e1fd524f9dd236ce6b1a76cc0"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"lllyasviel/stable-diffusion-webui-forge:metadata","source_url":"https://github.com/lllyasviel/stable-diffusion-webui-forge","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Avladmandic%2Fsdnext%20repo%3Alllyasviel%2Fstable-diffusion-webui-forge%20repo%3APaddlePaddle%2FPaddleOCR%20repo%3AUmi-OCR%2FUmi-OCR%20repo%3Apenpot%2Fpenpot%20repo%3Aexcalidraw%2Fexcalidraw%20repo%3Atldraw%2Ftldraw%20repo%3Aslidevjs%2Fslidev&per_page=100","stars":12986,"forks":1714,"license":"AGPL-3.0"},"fetched_at":"2026-09-03T16:09:01.022Z"},{"source_type":"github","source_identifier":"lllyasviel/stable-diffusion-webui-forge:readme:e99a0cdc5711816a3da4edb1d70f41dcf3396a6e1fd524f9dd236ce6b1a76cc0","source_url":"https://raw.githubusercontent.com/lllyasviel/stable-diffusion-webui-forge/main/README.md","raw_metadata":{"sha256":"e99a0cdc5711816a3da4edb1d70f41dcf3396a6e1fd524f9dd236ce6b1a76cc0","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:39.617Z"}],"expected":null},{"identity":"repo:https://github.com/acly/krita-ai-diffusion","slug":"krita-ai-diffusion-e7ce1dee","name":"Krita AI Diffusion","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Vẽ và chỉnh vùng trong Krita, để AI hỗ trợ ngay trên canvas của bạn.","description":"Plugin này đưa tạo hình AI vào workflow vẽ của Krita: chọn vùng, dùng sketch/pose/ảnh tham chiếu rồi chỉnh tiếp bằng công cụ quen thuộc. Nó phù hợp creator muốn giữ quyền điều khiển hình thay vì chấp nhận trọn vẹn một ảnh sinh tự động.","long_description":"ĐIỂM NỔI BẬT\n• Generative fill, mở rộng ảnh và live painting.\n• ControlNet, ảnh tham chiếu và prompt riêng theo vùng/layer.\n• Hàng đợi, lịch sử, preset và backend ComfyUI local hoặc kết nối server.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nVẽ phác bố cục thumbnail, cho AI bổ sung một vùng rồi chỉnh chữ bằng công cụ thiết kế để giữ chính xác.\n\nBẮT ĐẦU\nCài Krita tối thiểu 5.2 và plugin đúng nguồn, sau đó cấu hình server/model.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nĐây là plugin của Acly, không phải mọi hỗ trợ đều do đội Krita cung cấp. Chạy local cần phần cứng; cloud và model thêm có phí/điều khoản riêng.","canonical_url":"https://github.com/Acly/krita-ai-diffusion","repository_url":"https://github.com/Acly/krita-ai-diffusion","documentation_url":"https://raw.githubusercontent.com/Acly/krita-ai-diffusion/main/README.md","owner_name":"Acly","license":"GPL-3.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":65,"categories":["image","design"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Vẽ và chỉnh vùng trong Krita, để AI hỗ trợ ngay trên canvas của bạn. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Vẽ và chỉnh vùng trong Krita, để AI hỗ trợ ngay trên canvas của bạn.","highlights":["Generative fill, mở rộng ảnh và live painting.","ControlNet, ảnh tham chiếu và prompt riêng theo vùng/layer.","Hàng đợi, lịch sử, preset và backend ComfyUI local hoặc kết nối server."],"example":"Vẽ phác bố cục thumbnail, cho AI bổ sung một vùng rồi chỉnh chữ bằng công cụ thiết kế để giữ chính xác.","setup":"Cài Krita tối thiểu 5.2 và plugin đúng nguồn, sau đó cấu hình server/model.","limitations":"Đây là plugin của Acly, không phải mọi hỗ trợ đều do đội Krita cung cấp. Chạy local cần phần cứng; cloud và model thêm có phí/điều khoản riêng.","github":{"stars":10536,"forks":621,"observedAt":"2026-09-03T16:08:54.574Z","url":"https://github.com/Acly/krita-ai-diffusion","pushedAt":"2026-08-28T20:55:10Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/Acly/krita-ai-diffusion/main/README.md","observedAt":"2026-09-03T16:10:33.730Z","sha256":"abf4e65d970a420c192f20a01b6254cd6e8cc27b7d2dbe20647bb3330984d788"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"Acly/krita-ai-diffusion:metadata","source_url":"https://github.com/Acly/krita-ai-diffusion","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AAcly%2Fkrita-ai-diffusion%20repo%3ASanster%2FIOPaint%20repo%3Aupscayl%2Fupscayl%20repo%3Axinntao%2FReal-ESRGAN%20repo%3AQwenLM%2FQwen-Image%20repo%3Ablack-forest-labs%2Fflux%20repo%3ATencent-Hunyuan%2FHunyuan3D-2%20repo%3Amicrosoft%2FTRELLIS&per_page=100","stars":10536,"forks":621,"license":"GPL-3.0"},"fetched_at":"2026-09-03T16:08:54.574Z"},{"source_type":"github","source_identifier":"Acly/krita-ai-diffusion:readme:abf4e65d970a420c192f20a01b6254cd6e8cc27b7d2dbe20647bb3330984d788","source_url":"https://raw.githubusercontent.com/Acly/krita-ai-diffusion/main/README.md","raw_metadata":{"sha256":"abf4e65d970a420c192f20a01b6254cd6e8cc27b7d2dbe20647bb3330984d788","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:33.730Z"}],"expected":null},{"identity":"repo:https://github.com/qwenlm/qwen-image","slug":"qwen-image-0c09d432","name":"Qwen-Image","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Thử hình có chữ và chỉnh sửa ảnh với một họ model tập trung vào bố cục chữ.","description":"Qwen-Image hướng tới tạo hình và sửa ảnh, đặc biệt chú trọng chữ phức tạp. README có nhiều mốc phát hành như 2512, Edit-2511 và thông báo 2.0. Cần phân biệt model đã có trọng số tải với tính năng được giới thiệu qua dịch vụ.","long_description":"ĐIỂM NỔI BẬT\n• Tạo hình với chữ và bố cục phức tạp theo mô tả chính chủ.\n• Có các nhánh chỉnh sửa và Layered được dẫn riêng.\n• Cung cấp model card, báo cáo và ví dụ/demo để đối chiếu.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nThử bản nháp poster hoặc carousel, sau đó soát chính tả tiếng Việt và dựng lại phần chữ quan trọng nếu cần.\n\nBẮT ĐẦU\nChọn model/checkpoint có tài liệu tải rõ ràng và workflow tương thích.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nChất lượng chữ Trung được nhấn mạnh trong README không chứng minh chữ Việt hoàn hảo. Không lấy thông báo 2.0 để khẳng định mọi trọng số local cũ có đủ tính năng mới.","canonical_url":"https://github.com/QwenLM/Qwen-Image","repository_url":"https://github.com/QwenLM/Qwen-Image","documentation_url":"https://raw.githubusercontent.com/QwenLM/Qwen-Image/main/README.md","owner_name":"QwenLM","license":"Apache-2.0","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":66,"categories":["image","design","content"],"primaryCategory":"image","selectionReason":"Phù hợp Ảnh & Đồ họa AI: Thử hình có chữ và chỉnh sửa ảnh với một họ model tập trung vào bố cục chữ. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Thử hình có chữ và chỉnh sửa ảnh với một họ model tập trung vào bố cục chữ.","highlights":["Tạo hình với chữ và bố cục phức tạp theo mô tả chính chủ.","Có các nhánh chỉnh sửa và Layered được dẫn riêng.","Cung cấp model card, báo cáo và ví dụ/demo để đối chiếu."],"example":"Thử bản nháp poster hoặc carousel, sau đó soát chính tả tiếng Việt và dựng lại phần chữ quan trọng nếu cần.","setup":"Chọn model/checkpoint có tài liệu tải rõ ràng và workflow tương thích.","limitations":"Chất lượng chữ Trung được nhấn mạnh trong README không chứng minh chữ Việt hoàn hảo. Không lấy thông báo 2.0 để khẳng định mọi trọng số local cũ có đủ tính năng mới.","github":{"stars":8286,"forks":537,"observedAt":"2026-09-03T16:08:54.574Z","url":"https://github.com/QwenLM/Qwen-Image","pushedAt":"2026-02-10T07:37:37Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/QwenLM/Qwen-Image/main/README.md","observedAt":"2026-09-03T16:10:34.490Z","sha256":"12878946f055f1e1bd5f58e90891b845ad178171a71154dbb6a841dcb1fed5c6"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"QwenLM/Qwen-Image:metadata","source_url":"https://github.com/QwenLM/Qwen-Image","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3AAcly%2Fkrita-ai-diffusion%20repo%3ASanster%2FIOPaint%20repo%3Aupscayl%2Fupscayl%20repo%3Axinntao%2FReal-ESRGAN%20repo%3AQwenLM%2FQwen-Image%20repo%3Ablack-forest-labs%2Fflux%20repo%3ATencent-Hunyuan%2FHunyuan3D-2%20repo%3Amicrosoft%2FTRELLIS&per_page=100","stars":8286,"forks":537,"license":"Apache-2.0"},"fetched_at":"2026-09-03T16:08:54.574Z"},{"source_type":"github","source_identifier":"QwenLM/Qwen-Image:readme:12878946f055f1e1bd5f58e90891b845ad178171a71154dbb6a841dcb1fed5c6","source_url":"https://raw.githubusercontent.com/QwenLM/Qwen-Image/main/README.md","raw_metadata":{"sha256":"12878946f055f1e1bd5f58e90891b845ad178171a71154dbb6a841dcb1fed5c6","relationship":"MAINTAINER"},"fetched_at":"2026-09-03T16:10:34.490Z"}],"expected":null},{"identity":"repo:https://github.com/umami-software/umami","slug":"umami-bccea400","name":"Umami","type":"OPEN_SOURCE","status":"CANDIDATE","tagline":"Bài nào kéo người đọc về website? Hãy đo trước khi đoán.","description":"Umami là nền tảng analytics hướng tới quyền riêng tư, gom traffic, chiến dịch, hành vi và chuyển đổi trong một giao diện. Người làm content có thể dùng để xem bài social nào mang khách về trang, nội dung nào được đọc và hành động nào diễn ra sau đó. Có lựa chọn self-host hoặc cloud; đây là công cụ đo lường, không tự làm SEO.","long_description":"ĐIỂM NỔI BẬT\n• Theo dõi traffic và chiến dịch trong cùng hệ thống.\n• Hỗ trợ sự kiện/chuyển đổi để gắn lượt đọc với mục tiêu cụ thể.\n• Có Docker và hướng dẫn tự triển khai với PostgreSQL.\n\nGỢI Ý ỨNG DỤNG (CHƯA PHẢI CASE STUDY)\nGắn tham số chiến dịch vào link đăng Facebook và LinkedIn, so sánh lượt về bài review và click sang nguồn tool để chọn kênh phân phối.\n\nBẮT ĐẦU\nTriển khai hoặc chọn cloud, thêm website và mã đo theo tài liệu; đổi tài khoản mặc định và bảo vệ quyền quản trị trước khi dùng thật.\n\nCẦN BIẾT TRƯỚC KHI DÙNG\nTrình chặn quảng cáo và cấu hình tracking có thể làm thiếu dữ liệu. Không tự động đồng nghĩa tuân thủ mọi quy định riêng tư; chỉ thu thập những sự kiện thực sự cần thiết.","canonical_url":"https://github.com/umami-software/umami","repository_url":"https://github.com/umami-software/umami","documentation_url":"https://raw.githubusercontent.com/umami-software/umami/master/README.md","owner_name":"umami-software","license":"MIT","import_metadata":{"creatorCatalog":{"edition":"creator-100-v1","selected":true,"rank":67,"categories":["seo","social"],"primaryCategory":"seo","selectionReason":"Phù hợp SEO & Analytics: Bài nào kéo người đọc về website? Hãy đo trước khi đoán. Có README chính chủ và số liệu GitHub đã đối chiếu; thứ tự là ưu tiên biên tập, không phải xếp hạng toàn GitHub.","hook":"Bài nào kéo người đọc về website? Hãy đo trước khi đoán.","highlights":["Theo dõi traffic và chiến dịch trong cùng hệ thống.","Hỗ trợ sự kiện/chuyển đổi để gắn lượt đọc với mục tiêu cụ thể.","Có Docker và hướng dẫn tự triển khai với PostgreSQL."],"example":"Gắn tham số chiến dịch vào link đăng Facebook và LinkedIn, so sánh lượt về bài review và click sang nguồn tool để chọn kênh phân phối.","setup":"Triển khai hoặc chọn cloud, thêm website và mã đo theo tài liệu; đổi tài khoản mặc định và bảo vệ quyền quản trị trước khi dùng thật.","limitations":"Trình chặn quảng cáo và cấu hình tracking có thể làm thiếu dữ liệu. Không tự động đồng nghĩa tuân thủ mọi quy định riêng tư; chỉ thu thập những sự kiện thực sự cần thiết.","github":{"stars":38580,"forks":7929,"observedAt":"2026-09-03T16:08:09.166Z","url":"https://github.com/umami-software/umami","pushedAt":"2026-09-02T21:56:41Z","archived":false},"readme":{"url":"https://raw.githubusercontent.com/umami-software/umami/master/README.md","observedAt":"2026-09-03T16:09:45.222Z","sha256":"6643804843e56264f15bcbf38245e439cde4af5fea1d01441bef7e925105b82e"},"trending":null,"extraSources":[]},"verification":"official_readme_editorial_not_runtime_tested","securityReview":"NOT_REVIEWED"},"sources":[{"source_type":"github","source_identifier":"umami-software/umami:metadata","source_url":"https://github.com/umami-software/umami","raw_metadata":{"metadataUrl":"https://api.github.com/search/repositories?q=repo%3Atowfiqi%2Fserpbear%20repo%3Aumami-software%2Fumami%20repo%3Aplausible%2Fanalytics%20repo%3Amatomo-org%2Fmatomo%20repo%3Aposthog%2Fposthog%20repo%3Aremotion-dev%2Fremotion%20repo%3Aheygen-com%2Fhyperframes%20repo%3Aharry0703%2FMoneyPrinterTurbo&per_page=100","stars":38580,"forks":7929,"license":"MIT"},"fetched_at":"2026-09-03T16:08:09.166Z"},{"source_type":"github","source_identifier":"umami-software/umami:readme:6643804843e56264f15bcbf38245e439cde4af5fea1d01441bef7e925105b82e","source_url":"https://raw.githubusercontent.com/umami-software/umami/master/README.md","raw_metadata":{"sha256":"6643804843e56264f15bcbf38245e439c